import { useState } from "react";
import "../styles/Dashboard.css";

export default function ShipperDashboard() {
  const [activeTab, setActiveTab] = useState("dashboard");

  const [orders, setOrders] = useState([
    { id: 1, customer: "Nguyễn Văn A", address: "123 Phố Cổ, Hà Nội", product: "Sản phẩm A", status: "Đang giao", distance: "5 km", phone: "0123456789" },
    { id: 2, customer: "Trần Thị B", address: "456 Lê Lợi, TP Hồ Chí Minh", product: "Sản phẩm B", status: "Chưa giao", distance: "3 km", phone: "0987654321" },
    { id: 3, customer: "Lê Văn C", address: "789 Hàng Bạc, Hà Nội", product: "Sản phẩm C", status: "Hoàn thành", distance: "0 km", phone: "0555555555" },
  ]);

  const [showOrderForm, setShowOrderForm] = useState(false);
  const [newOrder, setNewOrder] = useState({ customer: "", address: "", product: "", phone: "" });

  const handleAddOrder = () => {
    if (newOrder.customer && newOrder.address) {
      setOrders([...orders, { 
        id: orders.length + 1, 
        ...newOrder, 
        status: "Chưa giao",
        distance: "0 km"
      }]);
      setNewOrder({ customer: "", address: "", product: "", phone: "" });
      setShowOrderForm(false);
    }
  };

  const handleUpdateStatus = (id, newStatus) => {
    setOrders(orders.map(order => 
      order.id === id ? { ...order, status: newStatus } : order
    ));
  };

  const handleDeleteOrder = (id) => {
    setOrders(orders.filter(o => o.id !== id));
  };

  const completedOrders = orders.filter(o => o.status === "Hoàn thành").length;
  const ongoingOrders = orders.filter(o => o.status === "Đang giao").length;
  const pendingOrders = orders.filter(o => o.status === "Chưa giao").length;

  return (
    <div className="dashboard-container">
      <header className="dashboard-header">
        <div className="header-content">
          <h1>Dashboard Shipper</h1>
          <div className="header-info">
            <span className="user-info">🚚 Shipper</span>
            <button className="logout-btn">Đăng xuất</button>
          </div>
        </div>
      </header>

      <div className="dashboard-wrapper">
        <aside className="sidebar">
          <nav className="nav-menu">
            <button
              className={`nav-item ${activeTab === "dashboard" ? "active" : ""}`}
              onClick={() => setActiveTab("dashboard")}
            >
              📊 Dashboard
            </button>
            <button
              className={`nav-item ${activeTab === "orders" ? "active" : ""}`}
              onClick={() => setActiveTab("orders")}
            >
              📦 Đơn hàng
            </button>
            <button
              className={`nav-item ${activeTab === "map" ? "active" : ""}`}
              onClick={() => setActiveTab("map")}
            >
              🗺️ Bản đồ (Phát triển sau)
            </button>
          </nav>
        </aside>

        <main className="main-content">
          {/* Dashboard Tab */}
          {activeTab === "dashboard" && (
            <div className="content-section">
              <h2>Tổng quan Công việc</h2>
              <div className="stats-grid">
                <div className="stat-card">
                  <div className="stat-icon">📦</div>
                  <div className="stat-info">
                    <h3>Tổng Đơn hàng</h3>
                    <p className="stat-number">{orders.length}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">✅</div>
                  <div className="stat-info">
                    <h3>Hoàn thành</h3>
                    <p className="stat-number">{completedOrders}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">🚚</div>
                  <div className="stat-info">
                    <h3>Đang giao</h3>
                    <p className="stat-number">{ongoingOrders}</p>
                  </div>
                </div>
                <div className="stat-card">
                  <div className="stat-icon">⏳</div>
                  <div className="stat-info">
                    <h3>Chưa giao</h3>
                    <p className="stat-number">{pendingOrders}</p>
                  </div>
                </div>
              </div>

              <div className="dashboard-charts">
                <div className="chart-container">
                  <h3>Đơn hàng gần đây</h3>
                  {orders.slice(0, 5).map(order => (
                    <div key={order.id} className="order-item">
                      <div className="order-info">
                        <strong>{order.customer}</strong>
                        <p>{order.address}</p>
                        <span className={`status-badge status-${order.status.toLowerCase().replace(" ", "-")}`}>{order.status}</span>
                      </div>
                      <div className="order-distance">
                        📍 {order.distance}
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
          )}

          {/* Orders Tab */}
          {activeTab === "orders" && (
            <div className="content-section">
              <div className="section-header">
                <h2>Quản lý Đơn hàng</h2>
                <button className="btn-primary" onClick={() => setShowOrderForm(!showOrderForm)}>
                  ➕ Thêm Đơn hàng
                </button>
              </div>

              {showOrderForm && (
                <div className="form-container">
                  <h3>Thêm Đơn hàng mới</h3>
                  <input
                    type="text"
                    placeholder="Tên khách hàng"
                    value={newOrder.customer}
                    onChange={(e) => setNewOrder({ ...newOrder, customer: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Địa chỉ giao hàng"
                    value={newOrder.address}
                    onChange={(e) => setNewOrder({ ...newOrder, address: e.target.value })}
                  />
                  <input
                    type="text"
                    placeholder="Sản phẩm"
                    value={newOrder.product}
                    onChange={(e) => setNewOrder({ ...newOrder, product: e.target.value })}
                  />
                  <input
                    type="tel"
                    placeholder="Số điện thoại khách hàng"
                    value={newOrder.phone}
                    onChange={(e) => setNewOrder({ ...newOrder, phone: e.target.value })}
                  />
                  <button className="btn-success" onClick={handleAddOrder}>Lưu</button>
                  <button className="btn-secondary" onClick={() => setShowOrderForm(false)}>Hủy</button>
                </div>
              )}

              <table className="data-table">
                <thead>
                  <tr>
                    <th>ID</th>
                    <th>Khách hàng</th>
                    <th>Địa chỉ</th>
                    <th>Sản phẩm</th>
                    <th>Số điện thoại</th>
                    <th>Khoảng cách</th>
                    <th>Trạng thái</th>
                    <th>Hành động</th>
                  </tr>
                </thead>
                <tbody>
                  {orders.map(order => (
                    <tr key={order.id}>
                      <td>{order.id}</td>
                      <td>{order.customer}</td>
                      <td>{order.address}</td>
                      <td>{order.product}</td>
                      <td>{order.phone}</td>
                      <td>{order.distance}</td>
                      <td>
                        <select 
                          value={order.status} 
                          onChange={(e) => handleUpdateStatus(order.id, e.target.value)}
                          className={`status-select status-${order.status.toLowerCase().replace(" ", "-")}`}
                        >
                          <option value="Chưa giao">Chưa giao</option>
                          <option value="Đang giao">Đang giao</option>
                          <option value="Hoàn thành">Hoàn thành</option>
                        </select>
                      </td>
                      <td>
                        <button className="btn-danger" onClick={() => handleDeleteOrder(order.id)}>Xóa</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}

          {/* Map Tab */}
          {activeTab === "map" && (
            <div className="content-section">
              <div className="coming-soon">
                <h2>🗺️ Bản đồ Theo dõi</h2>
                <p>Chức năng này sẽ được phát triển trong phiên bản tới</p>
                <div className="map-placeholder">
                  <p>Khu vực bản đồ tương tác với định vị GPS</p>
                </div>
              </div>
            </div>
          )}
        </main>
      </div>
    </div>
  );
}
